export function currentApplication(record,event){return {...record,eventName:event?.name??record.eventName,eventDate:event?.date??record.eventDate,eventPlace:event?.place??record.eventPlace??'',eventDateAtRegistration:record.eventDateAtRegistration??record.eventDate}}
export function watchCatalog({sdk,db},onData,onError){let closed=false;const query=sdk.query(sdk.collection(db,'schoolEventCatalog'),sdk.where('published','==',true));const stop=sdk.onSnapshot(query,{includeMetadataChanges:true},snapshot=>{if(!closed)onData(snapshot.docs.map(doc=>({...doc.data(),id:doc.id})),{fromCache:snapshot.metadata.fromCache})},error=>{if(!closed)onError?.(error)});return ()=>{if(!closed){closed=true;stop()}}}
export function latestLoad(){let version=0;return {begin(){const current=++version;return ()=>current===version},cancel(){version++}}}
